WITH filtered AS (SELECT id, session_id, event_time, duration_sec, SUBSTRING(event_type, 1, 4) AS event_type_prefix, COALESCE(page, 'UNKNOWN') AS page_filled FROM web_events WHERE event_time > DATE '2023-10-15' AND event_time < '2024-05-01'), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN duration_sec >= 530 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, BIT_OR(duration_sec) AS duration_sec_bit_or, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, SUM(duration_sec) AS total_duration_sec FROM islands GROUP BY CASE WHEN duration_sec >= 530 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_duration_sec DESC;
